class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        cnt = Counter()
        for w in words:
            cnt.update(w)
        pairs = sum(v // 2 for v in cnt.values())
        odds = sum(v % 2 for v in cnt.values())
        ans = 0
        for L in sorted(len(w) for w in words):
            need = L // 2
            if pairs < need:
                break
            pairs -= need
            if L % 2 == 1:
                if odds > 0:
                    odds -= 1
                else:
                    pairs -= 1
                    odds += 1
                    if pairs < 0:
                        break
            ans += 1
        return ans

