    int maxPalindromesAfterOperations(vector<string>& words) {
        array<int,26> cnt{};
        vector<int> lens;
        for (auto& w : words) {
            lens.push_back(w.size());
            for (char c : w) cnt[c-'a']++;
        }
        long long pairs = 0; int odds = 0;
        for (int v : cnt) { pairs += v/2; odds += v%2; }
        sort(lens.begin(), lens.end());
        int ans = 0;
        for (int L : lens) {
            long long need = L/2;
            if (pairs < need) break;
            pairs -= need;
            if (L % 2 == 1) {
                if (odds > 0) odds--;
                else {
                    pairs--; odds++;
                    if (pairs < 0) break;
                }
            }
            ans++;
        }
        return ans;
    }
};

