            m = sum(1 for i in range(k) if lens[i] % 2 == 1)
            return m <= od + 2 * (tp - s)

        lo, hi = 0, len(words)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
