class Solution {
    public int maxPalindromesAfterOperations(String[] words) {
        int[] cnt = new int[26];
        int[] lens = new int[words.length];
        int idx = 0;
        for (String w : words) {
            lens[idx++] = w.length();
            for (char c : w.toCharArray()) cnt[c-'a']++;
        }
        long tp = 0; int od = 0;
        for (int v : cnt) { tp += v/2; od += v%2; }
        Arrays.sort(lens);
        int n = lens.length;
        long[] pre = new long[n];
        for (int i = 0; i < n; i++) pre[i] = (i > 0 ? pre[i-1] : 0) + lens[i]/2;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (ok(mid, lens, pre, tp, od)) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
    private boolean ok(int k, int[] lens, long[] pre, long tp, int od) {
        long s = pre[k-1];
        if (s > tp) return false;
        int m = 0;
        for (int i = 0; i < k; i++) if (lens[i] % 2 == 1) m++;
        return m <= od + 2 * (tp - s);
    }
}

